import Foundation
import Testing
@testable import KudzuCore

func t2ImportCase(_ source: String, file: String? = nil) throws -> T2FixtureTests.ImportCase { try #require(t2Fixture([T2FixtureTests.ImportCase].self,"interchange/imports.json").first { $0.source == source && (file == nil || $0.file == file) }) }
func t2Raycast() throws -> ImportResult { let c = try t2ImportCase("raycast"); return try Raycast.importJSON(c.text ?? "",fileName:c.file ?? "") }
func t2Plist() throws -> ImportResult { let c = try t2ImportCase("textexpander",file:"Work.textexpander"); return try TextExpander.importData(Data((c.text ?? "").utf8),fileName:c.file ?? "") }
func t2Snippet(_ r: ImportResult, _ name: String) throws -> Snippet { try #require(r.library.snippets.first { $0.name == name }) }
func t2Render(_ source: String) -> String { Template.render(source,context:RenderContext(now:KudzuDate.parse("2026-03-04T09:05:00Z")!,timeZone:.gmt,locale:Locale(identifier:"en_US"),clipboard:"clip")).text }
func t2Temp() throws -> URL { let p = FileManager.default.temporaryDirectory.appendingPathComponent("kudzu-t2-"+UUID().uuidString); try FileManager.default.createDirectory(at:p,withIntermediateDirectories:true); return p }

@Suite struct RaycastImportTests {
    @Test func datesRenderWithTheConvertedFormats() throws { let r = try t2Raycast(); #expect(t2Render(try t2Snippet(r,"Today").content) == "4 Mar 2026 / 09:05 / 4 Mar 2026 at 09:05 / Wednesday"); #expect(t2Render(try t2Snippet(r,"Custom date").content) == "2026-03-05 4 Jan 2026 09:35") }
    @Test func importsIntoOneRaycastGroup() throws { let r = try t2Raycast(), sig = try t2Snippet(r,"Email sign-off"); #expect(r.library.groups.count == 1); #expect(r.library.groups[0].name == "Raycast"); #expect(r.library.snippets.count == 9); #expect(sig.triggers == ["!bye"]); #expect(sig.content == "Best,\n{{cursor}}"); #expect(sig.fireMode == .immediate && sig.caseMode == .exact && sig.isEnabled); #expect(sig.groupID == r.library.groups[0].id) }
    @Test func datesUseRaycastDefaultsAndConvertOffsets() throws {
        let r = try t2Raycast(); #expect(try t2Snippet(r,"Today").content == #"{{date format="d MMM yyyy"}} / {{date format="HH:mm"}} / {{date format="d MMM yyyy 'at' HH:mm"}} / {{date format="EEEE"}}"#)
        #expect(try t2Snippet(r,"Custom date").content == #"{{date format="yyyy-MM-dd" offset="+1d"}} {{date format="d MMM yyyy" offset="-2m"}} {{date format="HH:mm" offset="+30min"}}"#)
    }
    @Test func offsetsWithSpacesBetweenPartsAreKept() throws { let r = try t2Raycast(); #expect(try t2Snippet(r,"Spaced offset").content == #"{{date format="yyyy-MM" offset="+2y5m"}}"#); #expect(!r.warnings.contains { $0.trigger == "!so" }) }
    @Test func clipboardModifiersAndHistoryOffsets() throws { let r = try t2Raycast(); #expect(try t2Snippet(r,"Paste").content == "{{clipboard}} {{clipboard trim=true}} {clipboard offset=1}"); #expect(r.warnings.filter { $0.trigger == "!p" }.count == 1); #expect(r.warnings.first { $0.trigger == "!p" }?.message.contains("clipboard history") == true) }
    @Test func argumentsBecomeFormControlsAndSnippetsLinkByName() throws { let r = try t2Raycast(), reply = try t2Snippet(r,"Reply"), sig = try t2Snippet(r,"Email sign-off"); #expect(reply.content == "Hi {{field name=\"Name\" default=\"there\"}},\n{{choice name=\"Tone\" options=\"formal|casual\" default=\"casual\"}}\n{{snippet id=\"\(sig.id.uuidString)\"}}"); #expect(!r.warnings.contains { $0.trigger == "!reply" }) }
    @Test func unsupportedPlaceholdersStayTextWithWarnings() throws { let r = try t2Raycast(); #expect(try t2Snippet(r,"Unsupported").content == #"{selection} {uuid} {snippet name="Nope"} {argument name="x" bogus}"#); #expect(r.warnings.filter { $0.trigger == "!u" }.count == 4) }
    @Test func literalBracesAndBackslashesSurvive() throws { #expect(t2Render(try t2Snippet(t2Raycast(),"Code").content) == #"fn main() { println!("{}", 1); } {clipboard} {{literal}} C:\path"#) }
    @Test func keywordlessSnippetsImportTurnedOff() throws { let r = try t2Raycast(), s = try t2Snippet(r,"No keyword"); #expect(s.triggers.isEmpty && !s.isEnabled); #expect(r.warnings.contains { $0.message.contains("no keyword") }) }
    @Test func skippedEntriesAreReported() throws { let r = try t2Raycast(); #expect(r.warnings.contains { $0.trigger == "!empty" && $0.message.contains("no text") }); #expect(r.warnings.contains { $0.matchIndex == 10 && $0.message.contains("isn't a snippet") }) }
    @Test func everyImportedTemplateParsesWithoutErrors() throws { for s in try t2Raycast().library.snippets { #expect(!Template.parse(s.content).diagnostics.contains { $0.severity == .error }) } }
    @Test func rejectsFilesThatAreNotRaycastExports() throws { for s in [#"{"formatVersion":1}"#,"not json","[1, 2]"] { #expect(throws:(any Error).self) { try Raycast.importJSON(s,fileName:"x.json") } }; let r = try Raycast.importJSON("[]",fileName:"x.json"); #expect(r.library.groups.isEmpty && r.library.snippets.isEmpty) }
    @Test func acceptsAByteOrderMark() throws { #expect(try Raycast.importJSON("\u{feff}[{\"name\":\"a\",\"text\":\"b\",\"keyword\":\"c\"}]",fileName:"x.json").library.snippets.count == 1) }
    @Test func detectionTellsRaycastFromKudzuJson() throws { let dir = try t2Temp(); defer { try? FileManager.default.removeItem(at:dir) }; let a = dir.appendingPathComponent("snippets.json"), b = dir.appendingPathComponent("library.json"); try Data((t2ImportCase("raycast").text ?? "").utf8).write(to:a); try Data(#"{"formatVersion":1,"groups":[],"snippets":[]}"#.utf8).write(to:b); #expect(try Coordinator.detectImportSource(a) == .raycast); #expect(try Coordinator.detectImportSource(b) == .kudzu); #expect(try Coordinator.loadImport(a).library.snippets.count == 9) }
}
@Suite struct TextExpanderImportTests {
    @Test func plistGroupsAndDates() throws { let r = try t2Plist(), sig = try t2Snippet(r,"Signature"), date = try t2Snippet(r,"ddate"); #expect(r.library.groups.count == 1); #expect(r.library.groups[0].name == "Work & Co"); #expect(sig.triggers == ["sig"]); #expect(sig.caseMode == .exact && sig.fireMode == .immediate); #expect(KudzuDate.formatWholeSeconds(sig.createdAt) == "2020-05-06T07:08:09Z"); #expect(KudzuDate.formatWholeSeconds(sig.updatedAt) == "2021-05-06T07:08:09Z"); #expect(sig.content == "Best regards,\n{{field name=\"Sender\" default=\"Me\"}}{{cursor}}"); #expect(date.caseMode == .propagate); #expect(date.content == #"{{date format="EEEE, MMMM d, yyyy"}}"#); #expect(t2Render(date.content) == "Wednesday, March 4, 2026") }
    @Test func nestedSnippetsResolveByPrefixedAbbreviation() throws { let r = try t2Plist(), sig = try t2Snippet(r,"Signature"); #expect(try t2Snippet(r,"both").content == "{{snippet id=\"\(sig.id.uuidString)\"}} + %snippet:missing% + {{clipboard}}"); #expect(r.warnings.contains { $0.trigger == "both" && $0.message.contains("missing") }) }
    @Test func richScriptsAndIncompleteSnippets() throws { let r = try t2Plist(); #expect(try t2Snippet(r,"rich").content == "Bold & 50% done"); #expect(r.warnings.contains { $0.trigger == "rich" && $0.message.contains("formatting") }); #expect(!r.library.snippets.contains { $0.name == "script" }); #expect(r.warnings.contains { $0.trigger == "script" && $0.message.contains("Script") }); #expect(r.warnings.contains { $0.trigger == "broken" && $0.message.contains("missing") }); let loose = try t2Snippet(r,"Loose"); #expect(loose.triggers.isEmpty && !loose.isEnabled); #expect(r.library.snippets.count == 5) }
    @Test func everyImportedTemplateParsesWithoutErrors() throws { for s in try t2Plist().library.snippets { #expect(!Template.parse(s.content).diagnostics.contains { $0.severity == .error }) } }
    @Test func csvWithHeaderGroupsAndMultilineCells() throws { let csv = "\u{feff}Abbreviation,Content,Label,Group\r\n;hi,\"Hello,\r\nworld %Y\",Greeting,Chat\r\n;bye,Bye,,Chat\r\n;x,X,,Other\r\n;no,,,\r\n", r = try TextExpander.importData(Data(csv.utf8),fileName:"export.csv"); #expect(r.library.groups.map(\.name) == ["Chat","Other"]); #expect(r.library.snippets.count == 3); #expect(try t2Snippet(r,"Greeting").triggers == [";hi"]); #expect(try t2Snippet(r,"Greeting").content == "Hello,\nworld {{date format=\"yyyy\"}}"); #expect(try t2Snippet(r,";bye").content == "Bye"); #expect(r.warnings.contains { $0.message.contains("no content") }) }
    @Test func csvWithTextexpandersOwnHeaderSkipsTheHeaderRow() throws { let r = try TextExpander.importData(Data("abbreviation,snippet,label\n;sig,Best regards,Sig\n".utf8),fileName:"export.csv"); #expect(r.library.snippets.count == 1); #expect(try t2Snippet(r,"Sig").triggers == [";sig"]) }
    @Test func csvWhoseFirstAbbreviationStartsWithAnAngleBracketIsNotAPlist() throws { #expect(try TextExpander.importData(Data("<sig,Hello\n".utf8),fileName:"x.csv").library.snippets[0].triggers == ["<sig"]) }
    @Test func csvSemicolonsInsideQuotesDoNotChangeTheDelimiter() throws { let r = try TextExpander.importData(Data("sig,\"Hi; there; you\",Signature\nb,plain,Lab\n".utf8),fileName:"x.csv"); #expect(try t2Snippet(r,"Signature").content == "Hi; there; you"); #expect(r.library.snippets.count == 2) }
    @Test func csvWithoutHeaderIsAbbreviationThenContent() throws { let r = try TextExpander.importData(Data(";a,Alpha\n;b,Beta,Bee\n".utf8),fileName:"plain.csv"); #expect(r.library.groups[0].name == "plain"); #expect(r.library.snippets.count == 2); #expect(try t2Snippet(r,"Bee").content == "Beta") }
    @Test func unreadableFilesSayWhatToDo() {
        for input in [Data("bplist00\0\u{1}".utf8),Data("PK\u{3}\u{4}rest".utf8)] { do { _ = try TextExpander.importData(input,fileName:"x.textexpander"); Issue.record("expected rejection") } catch { #expect(error.localizedDescription.contains("CSV")) } }
        for input in ["<plist><dict></dict></plist>","<plist><dict>",""] { #expect(throws:(any Error).self) { try TextExpander.importData(Data(input.utf8),fileName:"x.csv") } }
    }
    @Test func detectionAndLoadingByExtension() throws { let dir = try t2Temp(); defer { try? FileManager.default.removeItem(at:dir) }; let file = dir.appendingPathComponent("Work.textexpander"); try Data((t2ImportCase("textexpander",file:"Work.textexpander").text ?? "").utf8).write(to:file); #expect(try Coordinator.detectImportSource(file) == .textExpander); #expect(try Coordinator.loadImport(file).library.snippets.count == 5); #expect(throws:(any Error).self) { try TextExpander.importFile(dir) }; let other = dir.appendingPathComponent("notes.txt"); try Data("x".utf8).write(to:other); #expect(throws:(any Error).self) { try Coordinator.detectImportSource(other) } }
}
